package org.example;

import org.junit.jupiter.api.Test;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ListZipperTest {
    @Test
    void mergesEqualSizedStringListsTest()
    {
        List<String> listOne = List.of("Mark", "Seth", "Helly", "Irving");
        List<String> listTwo = List.of("Wilson", "Chase", "Gregory", "Cameron");

        ListZipper<String> zipper = new ListZipper<>(listOne, listTwo);

        List<String> result = zipper.zip();
        assertEquals(List.of("Mark", "Wilson", "Seth", "Chase", "Helly", "Gregory", "Irving", "Cameron"), result);
    }

    @Test
    void mergesEqualSizedIntListsTest()
    {
        List<Integer> listOne = List.of(10, 13, 50, 78, 29);
        List<Integer> listTwo = List.of(11, 34, 204, 4, 23);

        ListZipper<Integer> zipper = new ListZipper<>(listOne, listTwo);

        List<Integer> result = zipper.zip();
        assertEquals(List.of(10, 11, 13, 34, 50, 204, 78, 4, 29, 23), result);
    }

    @Test
    void mergesUnequalSizedStringListsTest()
    {
        List<String> listOne = List.of("Mark", "Seth", "Helly");
        List<String> listTwo = List.of("Wilson", "Chase", "Gregory", "Cameron");

        ListZipper<String> zipper = new ListZipper<>(listOne, listTwo);

        List<String> result = zipper.zip();
        assertEquals(List.of("Mark", "Wilson", "Seth", "Chase", "Helly", "Gregory", "Cameron"), result);
    }

    @Test
    void mergesUnequalSizedIntListsTest()
    {
        List<Integer> listOne = List.of(10, 13, 50, 78, 29);
        List<Integer> listTwo = List.of(11, 34, 204);

        ListZipper<Integer> zipper = new ListZipper<>(listOne, listTwo);

        List<Integer> result = zipper.zip();
        assertEquals(List.of(10, 11, 13, 34, 50, 204, 78, 29), result);
    }
}
